<script setup lang="ts">
/**
 * Markdown, rendered through the vocabulary (`design/components/markdown.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Text as TextVNode, isVNode } from 'vue'

import styles from '@polymorph/recipes/ai/markdown.module.css'
import MarkdownBody from './MarkdownBody.vue'
import Skeleton from '../structure/Skeleton.vue'
import type { CitationSource } from './SourceList.vue'

export type MarkdownSize = NonNullable<MarkdownProps['size']>

export interface MarkdownProps {
  /**
   * The body text step (Text's `sm` or `md`), which does not change the heading scale.
   */
  size?: 'sm' | 'md'
  /**
   * The reply's sources in numbered order, which turn each `[n]` in the prose into a Citation to
   * the nth source (without them, `[n]` stays text).
   */
  sources?: CitationSource[]
  /**
   * Whether more is coming, which renders unfinished constructs as text and shows a caret at the
   * end.
   */
  streaming?: boolean
}

defineOptions({ name: 'Markdown', inheritAttrs: false })

withDefaults(defineProps<MarkdownProps>(), { size: 'md', sources: () => [], streaming: false })
defineSlots<{ default: (props: Record<string, never>) => unknown }>()
// The text the caller put in a slot: its text nodes, in order, without the elements'.
const slotText = (slot: ((...args: never[]) => unknown) | undefined): string => {
  const read = (nodes: unknown): string =>
    typeof nodes === 'string'
      ? nodes
      : Array.isArray(nodes)
        ? nodes.map(read).join('')
        : isVNode(nodes) && nodes.type === TextVNode
          ? read(nodes.children)
          : ''
  return read(slot?.())
}
</script>

<template>
  <div
    :class="styles.root"
    :data-size="size"
    :data-state="streaming ? 'streaming' : undefined"
    :data-pending="streaming && slotText($slots.default).trim() === '' ? '' : undefined"
    :aria-busy="streaming ? true : undefined"
    data-member="markdown"
  >
    <Skeleton
      v-if="streaming && slotText($slots.default).trim() === ''"
      shape="text"
      :textStep="size"
      :width="9"
    />
    <MarkdownBody
      v-else
      :source="slotText($slots.default)"
      :size="size"
      :sources="sources"
      :streaming="streaming"
    />
  </div>
</template>
